    const h=helpers.eyeHeightOf?.(mv)??1.6;
    const cy=target.point.y+(target.kind==='crate'?.45:.35);
    const dx=target.point.x-mv.x,dz=target.point.z-mv.z,dy=cy-(mv.y+h);
