    memory.path=result?.path||[];memory.noRoute=!result;memory.time=now;memory.goal=result?.goal||null;
    memory.lastRisk=result?.riskStart??0;memory.progressTime=now;memory.progressX=mv.x;memory.progressZ=mv.z;
