 const spread=Math.tan(spreadDeg*ebPI/180),cy=aimPoint==='head'?hy:bh*.60;
 const centre=[0,cy,-distance];
 const u=[centre[0],centre[1]-eye,centre[2]];
 const len=Math.hypot(...u),dir=u.map(x=>x/len);
